import pathlib
p = pathlib.Path('/Users/guillaumeloulier/PhpstormProjects/oss/elephc/.claude/worktrees/streams-csv-signature/tests/codegen/io/gz_streams.rs')
t = p.read_text()
old = '''#[test]
fn test_a_program_without_gz_calls_carries_no_gz_declarations() {
    let asm = compile_to_asm("<?php var_dump(strlen(\\"hello\\"));\\n");
    assert!(
        !asm.contains("gzopen") && !asm.contains("gzgets"),
        "the gz prelude leaked into a program that never mentions it"
    );
}'''
new = '''#[test]
fn test_a_program_without_gz_calls_carries_no_gz_declarations() {
    let dir = make_cli_test_dir("elephc_gz_prelude_pay_for_use");
    let (user_asm, _runtime_asm, _required_libraries) = compile_source_to_asm_with_options(
        "<?php var_dump(strlen(\\"hello\\"));\\n",
        &dir,
        8_388_608,
        false,
        false,
    );
    assert!(
        !user_asm.contains("gzopen") && !user_asm.contains("gzgets"),
        "the gz prelude leaked into a program that never mentions it"
    );
    let _ = std::fs::remove_dir_all(&dir);
}'''
assert t.count(old) == 1, 'pay-for-use test not found'
p.write_text(t.replace(old, new))
print('gz_streams.rs: the pay-for-use test uses the real asm helper')
